[2847] = { en = "Wild Leather Armor", tier = 3,
  t = "Wild Leather-pantser",
  d = "$n, je wordt een heel bekwame leerbewerker! Ik ken een paar patronen die je misschien interessant vindt... Wild Leather-pantser! Wild Leather maakt gebruik van de krachtige en chaotische eigenschappen van wildvines. Die vind je in gebieden met weelderige planten, en ook op sommige wezens die daar leven. Voor mensen met jouw vaardigheid is er geen beter pantser dan wat je ervan maakt, gegarandeerd.$B$BIk zal je dit leren, maar je gaat dan wel een tijdje voor mij werken. De eerste prijs is gewoon tien stukken Thick Leather. Daarna bespreken we de details.",
  o = "Breng 10 Thick Leather naar Pratt McGrubben in Feathermoon Stronghold.",
  p = "Zoals ik al zei, werk je voor mij terwijl je leert over Wild Leather-pantser. Omdat wildvines zowel krachtig als chaotisch zijn, geven ze een willekeurig maar sterk voordeel aan het pantser dat je gaat maken, dat al sterk is. Deze kennis heb ik echter niet makkelijk gekregen.$B$BDe eerste prijs om dit proces te beginnen is tien stukken Thick Leather.$B$BAls dat klaar is, beginnen we aan het werk dat jij moet doen om de patronen te krijgen.",
  c = "Nou $N, ik ben blij dat je meedoet. Je hebt als leerbewerker een slimme keuze gemaakt. Zodra je een van de Wild Leather-stukken kunt maken, zullen dragers van leren pantser om jou roepen.$B$BLaten we aan het werk gaan. Waar wil je beginnen?",
  g = { {"bekwame", "skilled (bekwaam)"}, {"pantser", "armour"}, {"maakt gebruik van", "makes use of"}, {"chaotische", "chaotic (chaotisch)"}, {"eigenschappen", "properties (eigenschap)"}, {"weelderige", "lush (weelderig)"}, {"wezens", "creatures (wezen)"}, {"gegarandeerd", "guaranteed"}, {"bespreken", "to discuss"}, {"willekeurig", "random"}, {"voordeel", "benefit, advantage"}, {"echter", "however"}, {"dragers", "wearers (drager)"}, {"om jou roepen", "clamour for you"} },
},

[2848] = { en = "Wild Leather Shoulders", tier = 3,
  t = "Wild Leather-schouderstukken",
  d = "Wild Leather-schouderstukken ondersteunen het lichaam van de drager heel goed. Ze geven uitstekende bescherming aan de bovenarmen en aan de schouders zelf. Zoals bij elk Wild Leather-pantser krijgt het voorwerp een krachtig maar willekeurig voordeel als de wildvine erin wordt genaaid.$B$BVoor dit patroon heb ik zes Thick Armor Kits en een Wildvine nodig. Dat is vast niet te veel gevraagd voor jou.",
  o = "Breng 6 Thick Armor Kits en een Wildvine naar Pratt McGrubben in Feathermoon Stronghold.",
  p = "Heb je de zes Thick Armor Kits en de Wildvine die ik nodig heb?$B$BDenk niet dat het maken van armor kits saai werk is. Terwijl je je vak uitoefent op deze kits, ontwikkel je een vaste werkwijze. Die helpt je om de vaardigheden te krijgen voor het fijne werk dat nodig is voor Wild Leather-pantser.$B$BZie je, er is een echte reden voor wat je voor mij maakt...",
  c = "Deze armor kits zijn van degelijke kwaliteit, $N. Als ik één ding eis, niet alleen van mijn eigen werk maar ook van het werk van wie voor mij werkt, dan is het kwaliteit.$B$BJe hebt dit patroon goed verdiend. Ik hoop dat het jou evenveel oplevert als het mij heeft opgeleverd.",
  g = { {"schouderstukken", "shoulder pieces (schouderstuk)"}, {"ondersteunen", "to support"}, {"drager", "wearer"}, {"uitstekende", "excellent (uitstekend)"}, {"bescherming", "protection"}, {"genaaid", "sewn (naaien)"}, {"saai", "boring, monotonous"}, {"uitoefent", "practise (uitoefenen)"}, {"werkwijze", "working method"}, {"degelijke", "solid (degelijk)"}, {"eis", "demand (eisen)"}, {"oplevert", "brings, yields (opleveren)"} },
},

[2849] = { en = "Wild Leather Vest", tier = 3,
  t = "Wild Leather-vest",
  d = "Een Wild Leather-vest is het basisstuk van elke set Wild Leather-pantser. Het geraamte van het vest mengt zich met de wildvine. Zo ontstaat een product dat de romp zo goed mogelijk beschermt, terwijl de krachtige magie haar weg door het kledingstuk kan vinden.$B$BVoor dit patroon heb ik twee Turtle Scale Breastplates, twee paar Turtle Scale Gloves en een Wildvine nodig. Het is een grote bestelling, maar je zult weinig moeite hebben om die voor mij te leveren.",
  o = "Breng 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves en een Wildvine naar Pratt McGrubben in Feathermoon Stronghold.",
  p = "Heb je de twee Turtle Scale Breastplates en Gloves die ik besteld heb? En vergeet de wildvine niet!$B$BZelfs met de eerste patronen leren we dat de basis van een vorm goed werkt bij moeilijkere kledingstukken. Het zijn andere voorwerpen, maar de vorm van de Turtle Scale Breastplates bereidt je voor op de details die nodig zijn voor een Wild Leather-vest.$B$BEn de handschoenen... nou, die zijn gewoon voor mijzelf. Vergeet niet: je werkt voor mij!",
  c = "Dit zijn heel mooie stukken, $N. Door het vakmanschap en de zorg die erin zitten, zouden ze alleen al een paar zilverstukken meer opbrengen dan een gewoon stuk.$B$BJe hebt mijn bestelling geleverd, en daarvoor krijg je je beloning. De kennis om Wild Leather-vesten te maken is nu van jou!",
  g = { {"basisstuk", "staple, basic piece"}, {"geraamte", "frame"}, {"ontstaat", "is created (ontstaan)"}, {"romp", "torso"}, {"kledingstuk", "garment"}, {"moeite", "difficulty, effort"}, {"leveren", "to deliver, fill (an order)"}, {"bereidt je voor", "prepares you (voorbereiden)"}, {"handschoenen", "gloves (handschoen)"}, {"vakmanschap", "craftsmanship"}, {"zilverstukken", "silver pieces (zilverstuk)"}, {"opbrengen", "to fetch (a price)"} },
},

[2850] = { en = "Wild Leather Helmet", tier = 3,
  t = "Wild Leather-helm",
  d = "Een Wild Leather-helm geeft de drager uitstekende bescherming van de belangrijke delen van het hoofd, zonder dat hij minder comfortabel is. Zoals bij elk Wild Leather-pantser geeft de wildvine die erin verwerkt is het geraamte van de helm een krachtige maar willekeurige verbetering. Wie leer draagt, wil dit stuk zeker hebben!$B$BVoor dit patroon heb ik twee Nightscape Tunics, twee Nightscape Headbands en een Wildvine nodig. Lever deze bestelling en het patroon is van jou!",
  o = "Breng 2 Nightscape Tunics, 2 Nightscape Headbands en een Wildvine naar Pratt McGrubben in Feathermoon Stronghold.",
  p = "Ik wil dat je die tunieken en hoofdbanden maakt. Ik heb ook dat stuk wildvine nodig. Pas daarna deel ik mijn kennis over Wild Leather-helmen met je.$B$BHoofdbescherming is erg gewild bij avonturiers, of het nu een verrassend eenvoudige hoofdband is of een helm die het hele hoofd bedekt. De basis voor het maken van waardevolle hoofdbescherming blijft altijd hetzelfde, hoe die er ook uitziet.",
  c = "De Nightscape-uitrusting die je hebt geleverd, past perfect bij de bestelling, $N. Ik verwacht niet minder van een leerbewerker van jouw niveau.$B$BJe hebt dit patroon zeker verdiend. Ik geef het je zonder iets terug te vragen, en ik hoop dat je er goed aan verdient.",
  g = { {"verwerkt", "worked in, integrated (verwerken)"}, {"willekeurige", "random (willekeurig)"}, {"verbetering", "enhancement"}, {"tunieken", "tunics (tuniek)"}, {"hoofdbanden", "headbands (hoofdband)"}, {"hoofdbescherming", "head gear, head protection"}, {"gewild", "sought after, coveted"}, {"verrassend", "surprisingly, disarmingly"}, {"bedekt", "covers (bedekken)"}, {"uitrusting", "equipment"}, {"niveau", "level, calibre"}, {"verdient", "earn, profit (verdienen)"} },
},

[2851] = { en = "Wild Leather Boots", tier = 3,
  t = "Wild Leather-laarzen",
  d = "Je hebt nu al heel wat geleerd, $n. Toch is er nog meer te leren. Nu komen de Wild Leather-laarzen, de hoeksteen van elke set.$B$BDeze laarzen zijn gemaakt om de voet comfortabel te omsluiten en hem te beschermen tegen de gevaren van het avonturiersleven. De zachte zolen zijn een zegen voor wie zich stil wil bewegen.$B$BVoor dit patroon moet je een bestelling van twee Nightscape Pants en twee Nightscape Boots leveren. Ik heb ook twee wildvines nodig... niet maar één. Laat het me weten als je dit allemaal hebt.",
  o = "Breng 2 Nightscape Pants, 2 Nightscape Boots en 2 Wildvines naar Pratt McGrubben in Feathermoon Stronghold.",
  p = "De bestelling van de broeken, laarzen en wildvines moet eerst klaar zijn, dan pas krijg je het patroon, $N. Ben je klaar?$B$BVanaf het eerste paar laarzen dat we leren maken, begrijpen we dat een goede laars precies het evenwicht moet vinden tussen comfort en nut. Met allebei kunnen we voorwerpen maken waarmee de drager vermoeidheid kan negeren. Die vermoeidheid zou mensen met slechtere spullen verlammen.",
  c = "Weer heb je een ingewikkelde bestelling geleverd met de vaardigheid van een ervaren vakman. Je hebt dit patroon verdiend, en ook mijn dank.",
  g = { {"laarzen", "boots (laars)"}, {"hoeksteen", "cornerstone"}, {"omsluiten", "to enclose, cradle"}, {"avonturiersleven", "adventuring life"}, {"zolen", "soles (zool)"}, {"zegen", "blessing"}, {"evenwicht", "balance"}, {"nut", "use, function"}, {"vermoeidheid", "fatigue"}, {"negeren", "to ignore"}, {"verlammen", "to cripple, paralyse"}, {"ingewikkelde", "complex (ingewikkeld)"}, {"vakman", "professional, craftsman"} },
},

[2852] = { en = "Wild Leather Leggings", tier = 3,
  t = "Wild Leather-beenstukken",
  d = "Je kent de basis nu, $n, dus je bent klaar om moeilijker werk onder de knie te krijgen. Wild Leather-beenstukken behoren tot de stevigste en krachtigste leren uitrusting die er is. De taille, de dijen, de kuiten en de belangrijke organen krijgen allemaal enorme bescherming. Samen met de verbetering van de wildvine zullen avonturiers die ze hebben je bedanken, elke keer dat ze je zien.$B$BVoor dit patroon moet je een bestelling leveren van twee Turtle Scale Helms, twee Turtle Scale Bracers en twee wildvines.",
  o = "Breng 2 Turtle Scale Helms, 2 Turtle Scale Bracers en 2 Wildvines naar Pratt McGrubben in Feathermoon Stronghold.",
  p = "Heb je de Turtle Scale Bracers en Helms klaar? Vergeet de twee wildvines niet die ik nodig heb!$B$BInmiddels begin je te zien hoeveel kracht er in Wild Leather-pantser kan zitten. Een pantser dat je overal voor kunt gebruiken, is bijna onbetaalbaar voor een leerbewerker. De grenzen liggen alleen in de hoeveelheid grondstoffen om de voorwerpen te maken, niet in de kwaliteit van de eindproducten!",
  c = "Weer heb je een bestelling zonder fouten geleverd. Misschien kom ik op een dag bij JOU om kennis te vragen, hè $N?$B$BHier is het patroon voor de beenstukken, en ook mijn dank. Onthoud deze kennis goed, en laat je eindproducten gebruikmaken van je indrukwekkende vaardigheden!",
  g = { {"beenstukken", "leggings (beenstuk)"}, {"onder de knie te krijgen", "to master"}, {"stevigste", "sturdiest (stevig)"}, {"taille", "waist"}, {"dijen", "thighs (dij)"}, {"kuiten", "calves (kuit)"}, {"organen", "organs, vitals (orgaan)"}, {"inmiddels", "by now"}, {"onbetaalbaar", "invaluable, priceless"}, {"grenzen", "limits (grens)"}, {"hoeveelheid", "quantity"}, {"grondstoffen", "resources, raw materials (grondstof)"}, {"eindproducten", "finished products (eindproduct)"}, {"indrukwekkende", "impressive (indrukwekkend)"} },
},

[2853] = { en = "Master of the Wild Leather", tier = 3,
  t = "Meester van het Wild Leather",
  d = "Nou $n, jij bent echt de definitie van ijver. Er is nog één patroon over voor Wild Leather-pantser; de andere beheers je al. Ik laat je niet voor niets zwoegen voor dit patroon. Je hebt het al helemaal verdiend, en meer dan dat... maar ik kan het je niet zelf geven. Mijn leraar, die mij het vak heeft geleerd, moet jou belonen.$B$BBreng deze brief naar Telonis. Hij geeft les in leerbewerking in Darnassus. Laat hem de brief zien en laat hem jou erkennen als zijn gelijke, zoals ik dat doe.",
  o = "Geef Pratt's Letter aan Telonis, de meester-leerbewerker van Darnassus.",
  p = "Gegroet, $R... aan je gezicht zie ik dat je net als ik een leerbewerker bent. Ben je gekomen om iets van mijn vaardigheden te leren, of heb je iets anders met mij te bespreken?",
  c = "Ah ja, Pratt heeft je gestuurd. Hij is een mens, maar soms doet hij me aan ons, nachtelfen, denken. Zijn toewijding en zijn talent met leer zijn indrukwekkend. Dat hij je in deze brief zo prijst, is een teken van respect dat ik erken.$B$BIk weet dat hij je de kunst van Wild Leather heeft geleerd. Laat mij je opleiding afmaken met dit patroon. Gebruik het goed; weinig mensen in de wereld kennen de geheimen van Wild Leather-mantels.",
  g = { {"ijver", "diligence"}, {"beheers", "master (beheersen)"}, {"voor niets", "needlessly, for nothing"}, {"zwoegen", "to toil"}, {"belonen", "to reward"}, {"erkennen", "to acknowledge"}, {"gelijke", "equal"}, {"doet hij me aan ons denken", "he reminds me of us"}, {"nachtelfen", "night elves (nachtelf)"}, {"toewijding", "dedication"}, {"prijst", "praises (prijzen)"}, {"opleiding", "training"}, {"mantels", "cloaks (mantel)"} },
},

[7888] = { en = "Talismans of Merit", tier = 3,
  t = "Talismannen van verdienste",
  d = "Je hebt bewezen hoe waardevol je bent voor onze inspanningen in Warsong Gulch. Blijf onze zaak steunen en breng me meer talismannen van verdienste. Doe je dat, dan verdien je nog meer van ons vertrouwen.",
  o = "Je hebt voor je vorige opdracht een Silverwing Talisman of Merit ontvangen. Spreek me nog eens aan, dan ontvang je je beloning.",
  c = "Dank je, $N. Je heldendaden in Warsong Gulch weerklinken door heel Ashenvale Forest.",
  g = { {"talismannen", "talismans (talisman)"}, {"verdienste", "merit"}, {"bewezen", "proven (bewijzen)"}, {"inspanningen", "efforts (inspanning)"}, {"steunen", "to support"}, {"opdracht", "task, assignment"}, {"ontvangen", "received; receive"}, {"spreek me aan", "talk to me (aanspreken)"}, {"heldendaden", "heroic deeds (heldendaad)"}, {"weerklinken", "resound, ring (weerklinken)"} },
},

})

